llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Linezolid, a close oxazolidinone analogue sharing the same 2-oxazolidinone core and N-aryl morpholine motif, has almost 100% absolute oral bioavailability versus intravenous infusion in patients, directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "The lowest quantitative oral bioavailability among the retrieved evidence is praziquantel at 27.2% in patients with hepatic impairment, still above the 20% threshold; no experimental record supports F <20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Flecainide, a highly transferable drug with a different scaffold, has 70% absolute oral bioavailability (range 60-86%) in healthy subjects, supporting that the query's drug-like properties are consistent with F ≥20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a linezolid-like oxazolidinone; linezolid itself is almost completely absorbed orally, and all retrieved experimental F values are ≥27%, so the weight of evidence strongly supports F ≥20% (high).",
  "evidence_gaps": [
    "No direct experimental F measurement for the exact query molecule; the closest evidence is linezolid, not the query itself.",
    "The query's 5-chlorothiophene carboxamide and morpholin-3-one substituents could alter solubility or first-pass metabolism, but no evidence suggests they would reduce F below 20%."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C08"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "oxazolidinone linezolid analogues"
    }
  ],
  "revision_action": "initial"
}

